const KEY='nexo-control-v1';
const rootIdeas=[{id:'root',text:'NEXO',parent:null,x:50,y:49,horizon:'base',note:''}];
const defaults={ideas:rootIdeas,connections:[],events:[],places:[],movements:[],people:[],objectives:[],xls:null,webMetrics:[]};
function load(){try{return {...structuredClone(defaults),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return structuredClone(defaults)}}
let db=load();let page=location.hash.slice(1)||'ideas';let month=new Date();month.setDate(1);let selectedDay=new Date().toISOString().slice(0,10);let calView='month';let teamTab='equipo';let selectedPlace=null;let zoom=1;let panX=0,panY=0;let mapObj=null;let toastTimer;let connectionStart=null;let suggestions=[];let suggestionCache={};let suggestionLayer=null;let dataView='metrics';let webMetrics=[];let metricsWindow='30';
const oldIdeaSeeds=new Set(['producto','validacion','captacion','marketing','finanzasidea','legal','alianzas']);let removedSeeds=db.ideas.some(n=>oldIdeaSeeds.has(n.id));if(removedSeeds){db.ideas=db.ideas.filter(n=>!oldIdeaSeeds.has(n.id));db.ideas.forEach(n=>{if(oldIdeaSeeds.has(n.parent))n.parent='root'});db.connections=(db.connections||[]).filter(edge=>!edge.some(id=>oldIdeaSeeds.has(id)));save()}
let rootNode=db.ideas.find(n=>n.id==='root');if(rootNode?.note){rootNode.note='';save()}
const app=document.querySelector('#app');
const labels={ideas:'Mapa de ideas',calendario:'Calendario',territorio:'Territorio',finanzas:'Finanzas',equipo:'Datos de NEXO',contactos:'Contactos relevantes',objetivos:'Objetivos'};
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function money(n){return new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n)}
function dateFmt(s,opt={day:'numeric',month:'short'}){return s?new Intl.DateTimeFormat('es-AR',opt).format(new Date(s+'T12:00:00')):'—'}
function toast(t){let el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function head(kicker,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function modal(title,body){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" data-close><section class="modal" role="dialog" aria-modal="true"><header class="modal-head"><h2>${title}</h2><button class="modal-close" data-close aria-label="Cerrar">×</button></header>${body}</section></div>`}
function closeModal(){document.querySelector('#modal-root').innerHTML=''}
function field(label,name,value='',type='text',placeholder=''){return `<label class="field">${label}<input class="input" name="${name}" type="${type}" value="${esc(value)}" placeholder="${placeholder}" ${label.includes('*')?'required':''}></label>`}
function selectField(label,name,options,value){return `<label class="field">${label}<select class="select" name="${name}">${options.map(x=>`<option ${x[0]===value?'selected':''} value="${esc(x[0])}">${esc(x[1])}</option>`).join('')}</select></label>`}
function textarea(label,name,value='',placeholder=''){return `<label class="field">${label}<textarea name="${name}" placeholder="${placeholder}">${esc(value)}</textarea></label>`}
function form(body,submit='Guardar'){return `<form class="modal-form">${body}<div class="form-actions"><button class="btn" type="button" data-close>Cancelar</button><button class="btn btn-primary" type="submit">${submit}</button></div></form>`}
function pill(text,cls='gray'){return `<span class="pill pill-${cls}">${esc(text)}</span>`}
function classForStatus(s){return ({'Sin investigar':'gray','Pendiente de visita':'amber','Contactado':'blue','Visitado':'green','Oportunidad interesante':'blue','Descartado':'red','Pendiente':'amber','Planificado':'blue','Confirmado':'green','Realizado':'gray','Cancelado':'red','En curso':'blue','Completado':'green','Activo':'green','Inactivo':'gray'})[s]||'gray'}
function render(){document.querySelector('#crumb-current').textContent=labels[page]||labels.ideas;document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.title=`${labels[page]||'NEXO'} · NEXO Control`;({ideas:renderIdeas,calendario:renderCalendar,territorio:renderTerritory,finanzas:renderFinance,equipo:renderData,contactos:renderContacts,objetivos:renderObjectives}[page]||renderIdeas)();document.querySelectorAll('.event-chip').forEach(x=>x.draggable=true)}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'ideas';render()});window.addEventListener('leafletready',()=>{if(page==='territorio')renderTerritory()});
document.querySelector('#today-label').textContent=new Intl.DateTimeFormat('es-AR',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date());
document.querySelector('#help-button').onclick=()=>modal('Privacidad y almacenamiento',`<div class="modal-form"><p class="small-muted" style="line-height:1.7">Los cambios se guardan en el almacenamiento local de este navegador. Siguen disponibles al recargar, pero todavía no se comparten con otros dispositivos ni integrantes del equipo. El fondo cartográfico usa OpenStreetMap y requiere conexión a internet.</p><div class="form-actions"><button class="btn btn-primary" data-close>Entendido</button></div></div>`);
document.querySelector('#user-button').onclick=()=>toast('Espacio local de NEXO Control');

// Editor de ideas, fiel al lienzo protagonista y a la barra lateral del primer boceto.
function renderIdeas(){
 const legend=[['now','#45ae83','Inmediato'],['short','#6280ea','Corto plazo'],['medium','#d9ad36','Mediano plazo'],['long','#e68a4a','Largo plazo'],['wait','#9ca5b2','En espera'],['base','#344d70','NEXO']];
 app.innerHTML=head('ESTRATEGIA · ESPACIO DE TRABAJO','Mapa de ideas','Conectá ideas, planes y próximos pasos en un mismo lienzo.',`<button class="btn btn-primary" data-action="add-idea">＋ Nueva idea</button>`)+
 `<div class="ideas-layout"><aside class="card toolbox"><h2 class="tool-title">Herramientas</h2><div class="tool-group"><span class="tool-label">Lienzo</span><div class="tool-row" data-action="add-idea">＋<span>Nueva idea</span><span>↵</span></div><div class="tool-row" data-action="connect">⌁<span>Conectar ideas</span><span>⌘</span></div><div class="tool-row" data-action="tidy">✣<span>Ordenar mapa</span><span>↗</span></div></div><div class="tool-group"><span class="tool-label">Horizonte</span>${legend.slice(0,5).map(x=>`<div class="tool-row" data-filter-horizon="${x[0]}"><i class="color-dot" style="background:${x[1]}"></i><span>${x[2]}</span><span>${db.ideas.filter(n=>n.horizon===x[0]).length}</span></div>`).join('')}</div><div class="legend"><span class="tool-label">Convenciones</span>${legend.slice(0,5).map(x=>`<div class="legend-row"><i class="color-dot" style="background:${x[1]}"></i>${x[2]}</div>`).join('')}</div></aside>
 <section class="card idea-canvas" id="idea-canvas"><div class="canvas-head"><button class="btn" data-action="add-idea">＋ Idea</button><button class="btn" data-action="connect">⌁ Conectar</button><button class="btn" data-action="delete-idea">⌫ Eliminar</button></div><div class="canvas-controls"><button data-zoom="out" aria-label="Alejar">−</button><span class="zoom-level">${Math.round(zoom*100)}%</span><button data-zoom="in" aria-label="Acercar">＋</button><button data-action="reset-zoom" title="Restablecer">⤢</button></div><div class="canvas-area" id="canvas-area" style="transform:translate(${panX}px,${panY}px) scale(${zoom})"><svg class="edges" id="edges"></svg>${db.ideas.length===1?'<div class="canvas-empty-hint"><b>Tu mapa empieza acá</b><span>Agregá ideas y conectalas a tu manera.</span></div>':''}${db.ideas.map(n=>{let h=legend.find(x=>x[0]===n.horizon)||legend[4];return `<div class="mind-node ${n.id==='root'?'root':''}" data-node="${n.id}" style="left:${n.x}%;top:${n.y}%;--node-color:${h[1]}">${esc(n.text)}${n.note?`<small>${esc(n.note)}</small>`:''}</div>`}).join('')}</div></section></div>`;
 drawEdges();wireIdeaCanvas();enableCanvasMotion();
}
function enableCanvasMotion(){let area=document.querySelector('#idea-canvas'),canvas=document.querySelector('#canvas-area');if(!area||!canvas)return;let drag=null;area.onpointerdown=e=>{if(e.button!==0||e.target.closest('.mind-node,.canvas-controls,.canvas-head'))return;drag={x:e.clientX,y:e.clientY,px:panX,py:panY};area.setPointerCapture(e.pointerId);area.classList.add('panning')};area.onpointermove=e=>{if(!drag)return;panX=drag.px+e.clientX-drag.x;panY=drag.py+e.clientY-drag.y;canvas.style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`};area.onpointerup=e=>{drag=null;area.classList.remove('panning')};area.onpointercancel=area.onpointerup;area.onwheel=e=>{e.preventDefault();zoom=Math.max(.55,Math.min(1.65,zoom+(e.deltaY<0?.08:-.08)));canvas.style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`;area.querySelector('.zoom-level').textContent=`${Math.round(zoom*100)}%`}}
function drawEdges(){let svg=document.querySelector('#edges'),canvas=document.querySelector('#idea-canvas');if(!svg||!canvas)return;let r=canvas.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${r.width} ${r.height}`);svg.innerHTML=db.ideas.filter(n=>n.parent).map(n=>{let p=db.ideas.find(x=>x.id===n.parent);return p?`<line class="edge-line" x1="${p.x*r.width/100}" y1="${p.y*r.height/100}" x2="${n.x*r.width/100}" y2="${n.y*r.height/100}"/>`:''}).join('')+(db.connections||[]).map(c=>{let a=db.ideas.find(n=>n.id===c[0]),b=db.ideas.find(n=>n.id===c[1]);return a&&b?`<line class="edge-line" stroke-dasharray="4 4" x1="${a.x*r.width/100}" y1="${a.y*r.height/100}" x2="${b.x*r.width/100}" y2="${b.y*r.height/100}"/>`:''}).join('')}
function wireIdeaCanvas(){let area=document.querySelector('#idea-canvas'),canvas=document.querySelector('#canvas-area');let dragged=null,sel=null,offset=[0,0];canvas.querySelectorAll('.mind-node').forEach(el=>{el.addEventListener('pointerdown',e=>{let n=db.ideas.find(x=>x.id===el.dataset.node);sel=n.id;canvas.querySelectorAll('.mind-node').forEach(x=>x.classList.toggle('selected',x===el));if(n.id==='root'||connectionStart)return;dragged=n;el.setPointerCapture(e.pointerId);let cr=area.getBoundingClientRect();offset=[e.clientX-cr.left-(n.x*cr.width/100),e.clientY-cr.top-(n.y*cr.height/100)];e.preventDefault()});el.addEventListener('pointermove',e=>{if(!dragged)return;let cr=area.getBoundingClientRect();dragged.x=Math.max(4,Math.min(96,(e.clientX-cr.left-offset[0])/cr.width*100));dragged.y=Math.max(7,Math.min(93,(e.clientY-cr.top-offset[1])/cr.height*100));el.style.left=dragged.x+'%';el.style.top=dragged.y+'%';drawEdges()});el.addEventListener('pointerup',()=>{if(dragged){dragged=null;save()}});el.addEventListener('click',()=>{if(!connectionStart)return;if(connectionStart===el.dataset.node){toast('Elegí otra idea para conectarla');return}db.connections=db.connections||[];if(!db.connections.some(c=>c.includes(connectionStart)&&c.includes(el.dataset.node)))db.connections.push([connectionStart,el.dataset.node]);connectionStart=null;save();renderIdeas();toast('Ideas conectadas')});el.ondblclick=()=>openIdea(el.dataset.node)});area.querySelectorAll('[data-action="add-idea"]').forEach(x=>x.onclick=()=>openIdea());area.querySelectorAll('[data-action="connect"]').forEach(x=>x.onclick=()=>{if(!sel){toast('Seleccioná la primera idea y presioná Conectar');return}connectionStart=sel;toast('Ahora seleccioná la segunda idea')});area.querySelectorAll('[data-action="delete-idea"]').forEach(x=>x.onclick=()=>{let id=canvas.querySelector('.mind-node.selected')?.dataset.node;if(!id||id==='root'){toast('Seleccioná una idea para eliminar');return}db.ideas=db.ideas.filter(n=>n.id!==id&&n.parent!==id);db.connections=(db.connections||[]).filter(c=>!c.includes(id));save();renderIdeas();toast('Idea eliminada')});area.querySelectorAll('[data-action="tidy"]').forEach(x=>x.onclick=()=>{let arr=db.ideas.filter(n=>n.id!=='root');arr.forEach((n,i)=>{let a=-Math.PI/2+i*2*Math.PI/arr.length;n.x=50+32*Math.cos(a);n.y=50+35*Math.sin(a)});save();renderIdeas();toast('Mapa ordenado')});area.querySelectorAll('[data-zoom]').forEach(x=>x.onclick=()=>{zoom=Math.max(.65,Math.min(1.5,zoom+(x.dataset.zoom==='in'?.1:-.1)));renderIdeas()});area.querySelector('[data-action="reset-zoom"]').onclick=()=>{zoom=1;panX=0;panY=0;renderIdeas()};area.querySelectorAll('[data-filter-horizon]').forEach(x=>x.onclick=()=>{let h=x.dataset.filterHorizon;canvas.querySelectorAll('.mind-node').forEach(n=>n.style.opacity=db.ideas.find(i=>i.id===n.dataset.node)?.horizon===h||n.dataset.node==='root'?1:.25)})}
function openIdea(id){let n=db.ideas.find(x=>x.id===id);modal(n?'Editar idea':'Nueva idea',form(`${field('Idea *','text',n?.text||'','','Ej. Validar con 5 restaurantes')}${textarea('Nota','note',n?.note||'')}${selectField('Horizonte temporal','horizon',[['now','Inmediato'],['short','Corto plazo'],['medium','Mediano plazo'],['long','Largo plazo'],['wait','En espera']],n?.horizon||'short')}${n?selectField('Conectar con','parent',[['','Sin conexión'],...db.ideas.filter(i=>i.id!==n.id).map(i=>[i.id,i.text])],n.parent||''):selectField('Rama principal','parent',db.ideas.map(i=>[i.id,i.text]),'root')}`,n?'Guardar cambios':'Crear idea'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));if(n)Object.assign(n,f);else db.ideas.push({id:uid(),...f,x:22+Math.random()*55,y:28+Math.random()*43});save();closeModal();renderIdeas();toast(n?'Idea actualizada':'Idea creada')}}

// Calendario mensual/semanal/agenda, con formulario y selección de día.
function renderCalendar(){let y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset);let count=calView==='month'?42:calView==='week'?7:0;let dates=count?Array.from({length:count},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);return d}):[];let shownEvents=db.events.filter(e=>(!eventFilter||e.category===eventFilter)&&(!statusFilter||e.status===statusFilter));let weekLabel=dates.length?`${dateFmt(dates[0].toISOString().slice(0,10))} — ${dateFmt(dates.at(-1).toISOString().slice(0,10),{day:'numeric',month:'long'})}`:new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(month);if(calView==='month')weekLabel=new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(month);let cells=calView==='agenda'?`<div class="empty"><span class="empty-icon">☷</span><b>Agenda de eventos</b><p>Eventos programados, ordenados por fecha.</p>${shownEvents.length?shownEvents.sort((a,b)=>a.date.localeCompare(b.date)).map(eventRow).join(''):''}</div>`:`<div class="weekdays">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>`<div>${x}</div>`).join('')}</div><div class="days-grid">${dates.map(d=>{let key=d.toISOString().slice(0,10),items=shownEvents.filter(e=>e.date===key);return `<div class="day ${d.getMonth()!==m?'other':''} ${key===selectedDay?'selected':''} ${key===new Date().toISOString().slice(0,10)?'today':''}" data-day="${key}"><span class="day-number">${d.getDate()}</span>${items.slice(0,2).map(e=>`<div class="event-chip cat-${slug(e.category)}" data-event="${e.id}">${esc(e.title)}</div>`).join('')}${items.length>2?`<span class="small-muted">+${items.length-2} más</span>`:''}</div>`}).join('')}</div>`;
 app.innerHTML=head('AGENDA · EVENTOS','Calendario de eventos','Organizá encuentros, visitas y oportunidades para NEXO.',`<button class="btn btn-primary" data-action="add-event">＋ Nuevo evento</button>`)+`<div class="filters-row" style="margin-bottom:12px">${selectField('','filter-category',[['','Todas las categorías'],['Networking','Networking'],['Reunión','Reunión'],['Visita','Visita'],['Feria','Feria'],['Capacitación','Capacitación'],['Otro','Otro']],eventFilter||'')}${selectField('','filter-status',[['','Todos los estados'],['Pendiente de investigar','Por investigar'],['Planificado','Planificado'],['Confirmado','Confirmado'],['Realizado','Realizado'],['Cancelado','Cancelado']],statusFilter||'')}</div><div class="calendar-grid"><section class="card calendar-card"><header class="card-head"><div class="calendar-toolbar"><button class="arrow-btn" data-cal="prev">‹</button><button class="arrow-btn" data-cal="next">›</button><span class="month-title">${weekLabel}</span></div><div class="toolbar"><div class="view-switch">${[['month','Mes'],['week','Semana'],['agenda','Agenda']].map(x=>`<button data-view="${x[0]}" class="${calView===x[0]?'active':''}">${x[1]}</button>`).join('')}</div></div></header><div class="calendar-table">${cells}</div></section><aside class="card calendar-side"><section><div class="card-head"><h2 class="card-title">${dateFmt(selectedDay,{weekday:'long',day:'numeric',month:'long'})}</h2><button class="btn btn-sm" data-action="add-event">＋ Agregar</button></div><div class="day-detail">${shownEvents.filter(e=>e.date===selectedDay).length?shownEvents.filter(e=>e.date===selectedDay).map(eventRow).join(''):`<div class="empty" style="padding:18px 8px"><span class="empty-icon">◷</span><b>Un día libre para nuevas ideas</b><p>Sumá una visita o encuentro a tu agenda.</p></div>`}</div></section><section class="side-section"><h3>Próximos eventos</h3>${shownEvents.filter(e=>e.date>=new Date().toISOString().slice(0,10)).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4).map(e=>`<div class="upcoming"><div class="date-block"><b>${new Date(e.date+'T12:00:00').getDate()}</b><small>${new Intl.DateTimeFormat('es-AR',{month:'short'}).format(new Date(e.date+'T12:00:00')).toUpperCase()}</small></div><div><b>${esc(e.title)}</b><small>${esc(e.category)} · ${esc(e.time||'Sin horario')}</small></div></div>`).join('')||'<p class="small-muted">Todavía no hay eventos próximos.</p>'}</section></aside></div>`;
 app.querySelectorAll('[data-action="add-event"]').forEach(b=>b.onclick=()=>openEvent());app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{calView=b.dataset.view;renderCalendar()});app.querySelector('[data-cal="prev"]').onclick=()=>{month.setDate(1);month.setMonth(month.getMonth()-(calView==='week'?0:1));if(calView==='week')month.setDate(month.getDate()-7);renderCalendar()};app.querySelector('[data-cal="next"]').onclick=()=>{month.setDate(1);month.setMonth(month.getMonth()+(calView==='week'?0:1));if(calView==='week')month.setDate(month.getDate()+7);renderCalendar()};app.querySelector('[name="filter-category"]').onchange=e=>{eventFilter=e.target.value;renderCalendar()};app.querySelector('[name="filter-status"]').onchange=e=>{statusFilter=e.target.value;renderCalendar()};app.querySelectorAll('[data-day]').forEach(d=>d.onclick=e=>{if(e.target.closest('[data-event]')){let ev=db.events.find(x=>x.id===e.target.closest('[data-event]').dataset.event);openEvent(ev?.id);return}selectedDay=d.dataset.day;renderCalendar()});app.querySelectorAll('[data-event]').forEach(el=>el.onclick=e=>{e.stopPropagation();openEvent(el.dataset.event)});
}
let eventFilter='',statusFilter='';function slug(s=''){return s.toLowerCase().replaceAll('í','i').replaceAll('é','e').replaceAll(' ','')}
function eventRow(e){return `<div class="event-item"><span class="event-marker"></span><div><b>${esc(e.title)}</b><small>${esc(e.time||'')}${e.time?' · ':''}${esc(e.category)} · ${esc(e.status)}</small></div><button data-edit-event="${e.id}" title="Editar">···</button></div>`}
function openEvent(id){let e=db.events.find(x=>x.id===id);modal(e?'Editar evento':'Nuevo evento',form(`${field('Nombre del evento *','title',e?.title||'','','Ej. Reunión de equipo')+field('Fecha *','date',e?.date||selectedDay,'date')}${field('Horario','time',e?.time||'','time')}${field('Lugar','place',e?.place||'','','Dirección o enlace')}${selectField('Categoría','category',['Networking','Reunión','Visita','Feria','Capacitación','Otro'].map(x=>[x,x]),e?.category||'Reunión')}${selectField('Estado','status',['Pendiente de investigar','Planificado','Confirmado','Realizado','Cancelado'].map(x=>[x,x]),e?.status||'Planificado')}${field('Responsable','owner',e?.owner||'')}${textarea('Descripción','description',e?.description||'')}`,e?'Guardar cambios':'Agregar a calendario'));document.querySelector('.modal-form').onsubmit=ev=>{ev.preventDefault();let f=Object.fromEntries(new FormData(ev.currentTarget));if(e)Object.assign(e,f);else db.events.push({id:uid(),...f});selectedDay=f.date;save();closeModal();renderCalendar();toast(e?'Evento actualizado':'Evento agregado')};if(e)document.querySelector('.modal-form').insertAdjacentHTML('beforeend','')}

// Mapa real de Mendoza. Se puede fijar un marcador haciendo clic sobre el mapa al crear un lugar.
function renderTerritory(){let places=db.places;let pend=places.filter(p=>['Sin investigar','Pendiente de visita'].includes(p.status)).length,done=places.filter(p=>['Visitado','Contactado','Oportunidad interesante'].includes(p.status)).length;app.innerHTML=head('INVESTIGACIÓN · MENDOZA','Territorio','Establecimientos, conversaciones y próximos pasos en campo.',`<div class="toolbar"><button class="btn" data-action="discover-places">✦ Sugerencias</button><button class="btn btn-primary" data-action="add-place">＋ Agregar lugar</button></div>`)+`<div class="summary-strip"><div class="card summary-mini"><span>Pendientes de visitar</span><b>${pend}</b></div><div class="card summary-mini"><span>Contactos realizados</span><b>${done}</b></div><div class="card summary-mini"><span>Lugares registrados</span><b>${places.length}</b></div></div><div class="territory-layout"><section class="card map-panel"><div id="map" style="position:absolute;inset:0"></div><div class="map-toolbar"><input class="input" id="place-search" placeholder="⌕  Buscar lugar o dirección…"><select class="select" id="place-category"><option value="">Todas las categorías</option>${['Restaurante','Bar','Hotel','Salón de eventos','Empresa gastronómica','Otro'].map(c=>`<option>${c}</option>`).join('')}</select><select class="select" id="place-status"><option value="">Todos los estados</option>${['Sin investigar','Pendiente de visita','Contactado','Visitado','Oportunidad interesante','Descartado'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="map-caption">OpenStreetMap · clic en el mapa para fijar un lugar nuevo</div></section><aside class="card place-card"><header class="place-head"><h2>${selectedPlace?esc(places.find(p=>p.id===selectedPlace)?.name||'Ficha del lugar'):'Ficha del lugar'}</h2><p>${selectedPlace?'Información y seguimiento':'Seleccioná un marcador o un lugar de la lista.'}</p></header><div class="place-scroll" id="place-detail">${selectedPlace?placeDetail(places.find(p=>p.id===selectedPlace)):places.length?places.map(p=>`<div class="upcoming" data-place-row="${p.id}" style="padding:11px 15px;cursor:pointer"><span class="event-marker" style="background:${placeColor(p.status)}"></span><div><b>${esc(p.name)}</b><small>${esc(p.category)} · ${esc(p.status)}</small></div></div>`).join(''):`<div class="empty"><span class="empty-icon">⌖</span><b>Empezá a explorar</b><p>Agregá establecimientos para planificar recorridos y registrar contactos.</p><button class="btn btn-sm" data-action="add-place">＋ Agregar lugar</button></div>`}</div>${selectedPlace?`<div class="place-actions"><button class="btn btn-sm" data-action="visit">＋ Registrar visita</button><button class="btn btn-sm" data-action="edit-place">Editar ficha</button></div>`:''}</aside></div>`;
 initLeaflet();plotSuggestions();document.querySelector('[data-action="discover-places"]')?.addEventListener('click',openSuggestions);document.querySelector('[data-action="add-place"]')?.addEventListener('click',()=>openPlace());document.querySelectorAll('[data-place-row]').forEach(x=>x.onclick=()=>{selectedPlace=x.dataset.placeRow;renderTerritory()});let search=document.querySelector('#place-search'),cat=document.querySelector('#place-category'),status=document.querySelector('#place-status');function filterMarkers(){document.querySelectorAll('.leaflet-marker-icon[data-pid]').forEach(el=>{let p=places.find(x=>x.id===el.dataset.pid);el.style.display=(!p||((!search.value||`${p.name} ${p.address}`.toLowerCase().includes(search.value.toLowerCase()))&&(!cat.value||p.category===cat.value)&&(!status.value||p.status===status.value)))?'':'none'})}search.oninput=filterMarkers;cat.onchange=filterMarkers;status.onchange=filterMarkers;document.querySelector('[data-action="edit-place"]')?.addEventListener('click',()=>openPlace(selectedPlace));document.querySelector('[data-action="visit"]')?.addEventListener('click',()=>openVisit(selectedPlace));}
function placeColor(s){return ({'Sin investigar':'#a8afb9','Pendiente de visita':'#d8a042','Contactado':'#7188ef','Visitado':'#4caf92','Oportunidad interesante':'#bd82cb','Descartado':'#a8afb9'})[s]||'#a8afb9'}
function placeDetail(p){if(!p)return '<div class="empty"><b>Ficha no encontrada</b></div>';return `<div class="place-facts"><div>${pill(p.status,classForStatus(p.status))} ${pill(p.category,'gray')}</div><div><div class="fact-label">Dirección</div><div class="fact-value">${esc(p.address||'Sin dirección registrada')}</div></div><div><div class="fact-label">Contacto</div><div class="fact-value">${esc([p.contact,p.phone,p.email].filter(Boolean).join(' · ')||'Sin datos de contacto')}</div></div><div><div class="fact-label">Notas</div><div class="fact-value">${esc(p.notes||'Sin observaciones todavía.')}</div></div><div><div class="fact-label">Historial de visitas</div><div class="fact-value">${(p.visits||[]).length?(p.visits||[]).map(v=>`${dateFmt(v.date,{day:'numeric',month:'short',year:'numeric'})}: ${esc(v.note||'Visita registrada')}`).join('<br>'):'Sin visitas registradas'}</div></div><div><div class="fact-label">Próximo paso</div><div class="fact-value">${esc(p.next||'Sin seguimiento pendiente')}</div></div></div>`}
function initLeaflet(){let el=document.querySelector('#map');if(!el)return;if(mapObj){mapObj.remove();mapObj=null}if(!window.L){el.innerHTML=`<svg class="map-art" viewBox="0 0 900 600" preserveAspectRatio="xMidYMid slice"><rect width="900" height="600" fill="#edf2ed"/><path d="M0 75 Q160 130 300 65T600 90T900 30 M0 500 Q190 420 330 500T610 455T900 520" fill="none" stroke="#dbe6dd" stroke-width="28"/><path d="M40 410 C150 350 230 370 300 275 S430 270 505 330 660 250 850 310M130 10 Q215 160 160 255T270 570 M570 0 Q520 130 655 200T630 580" fill="none" stroke="#fff" stroke-width="8"/><text x="43%" y="47%" fill="#82918e" font-size="22">Gran Mendoza</text></svg><div class="map-caption">Vista esquemática. Conectate a internet para el mapa detallado.</div>`;return}mapObj=L.map(el,{zoomControl:false}).setView([-32.8895,-68.8458],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(mapObj);installOfflineMap(el);L.control.zoom({position:'bottomright'}).addTo(mapObj);db.places.filter(p=>p.lat&&p.lng).forEach(p=>{let color=placeColor(p.status),icon=L.divIcon({className:'',html:`<span class="map-marker" style="--pin:${color}"><i>${esc(p.category.slice(0,1))}</i></span>`,iconSize:[27,27],iconAnchor:[13,26]});let marker=L.marker([Number(p.lat),Number(p.lng)],{icon}).addTo(mapObj);marker.bindTooltip(esc(p.name));marker.on('click',()=>{selectedPlace=p.id;renderTerritory()});marker.getElement()?.setAttribute('data-pid',p.id)});plotSuggestions();let suggestionPlotTimer;mapObj.on('zoomend moveend',()=>{clearTimeout(suggestionPlotTimer);suggestionPlotTimer=setTimeout(()=>plotSuggestions(),100)});mapObj.on('click',e=>{pendingCoords=e.latlng;openPlace(null,pendingCoords)});}
function installOfflineMap(el){let currentMap=mapObj,tile=Object.values(mapObj._layers).find(layer=>layer instanceof L.TileLayer),primaryLoaded=false,fallbackLoaded=false,fallbackLayer=null,fallbackStarted=false;el.insertAdjacentHTML('beforeend',`<div class="offline-map"><svg viewBox="0 0 900 600" preserveAspectRatio="xMidYMid slice"><rect width="900" height="600" fill="#edf2ed"/><path d="M0 75 Q160 130 300 65T600 90T900 30 M0 500 Q190 420 330 500T610 455T900 520" fill="none" stroke="#dbe6dd" stroke-width="28"/><path d="M40 410 C150 350 230 370 300 275 S430 270 505 330 660 250 850 310M130 10 Q215 160 160 255T270 570 M570 0 Q520 130 655 200T630 580" fill="none" stroke="#fff" stroke-width="8"/><path d="M55 135 L820 175 M30 290 L860 235 M90 470 L800 420 M230 20 L270 560 M420 0 L440 600 M700 0 L650 600" fill="none" stroke="#fff" stroke-width="4"/><g fill="#748985" font-family="sans-serif" font-size="14"><text x="390" y="290">MENDOZA</text><text x="180" y="215">Las Heras</text><text x="570" y="205">Guaymallén</text><text x="205" y="400">Godoy Cruz</text><text x="505" y="405">Maipú</text><text x="375" y="485">Luján de Cuyo</text><text x="630" y="90">Gran Mendoza</text></g><text x="30" y="570" fill="#84928d" font-family="sans-serif" font-size="11">Mapa simplificado · se volverá a cargar el mapa detallado al reconectar</text></svg></div>`);let showOffline=()=>{if(!primaryLoaded&&!fallbackLoaded)el.classList.add('offline')},hideOffline=()=>el.classList.remove('offline'),startFallback=()=>{if(mapObj!==currentMap||primaryLoaded||fallbackStarted)return;fallbackStarted=true;fallbackLayer=L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{subdomains:'abcd',maxZoom:20,attribution:'&copy; OpenStreetMap &copy; CARTO'}).addTo(currentMap);fallbackLayer.on('tileload',()=>{fallbackLoaded=true;hideOffline()});fallbackLayer.on('tileerror',showOffline)};if(tile){tile.on('tileload',()=>{primaryLoaded=true;hideOffline();if(fallbackLayer)currentMap.removeLayer(fallbackLayer)});tile.on('tileerror',()=>setTimeout(startFallback,900));setTimeout(startFallback,2200);setTimeout(showOffline,5200)}}
let pendingCoords=null;
function openSuggestions(){modal('Lugares sugeridos · Mendoza',`<div class="modal-form"><p class="small-muted" style="line-height:1.65">Busca establecimientos cercanos a la zona visible del mapa mediante OpenStreetMap. Los resultados no incluyen una clasificación de popularidad ni rating. Revisá cada lugar antes de agregarlo.</p>${selectField('Qué buscar','suggest-type',[['all','Restaurantes, bares, hoteles y eventos'],['food','Restaurantes y bares'],['hotels','Hoteles'],['events','Espacios para eventos']],'all')}<div class="toolbar"><button class="btn btn-primary" type="button" data-run-suggestions>⌕ Buscar en Mendoza</button><button class="btn" type="button" data-download-suggestions disabled>↓ Descargar CSV</button></div><div id="suggestion-results" class="suggestion-results"><div class="small-muted">Consulta datos abiertos al solicitar la búsqueda.</div></div><div class="form-actions"><button class="btn" type="button" data-close>Cerrar</button></div></div>`);document.querySelector('[data-run-suggestions]').onclick=loadPlaceSuggestions;document.querySelector('[data-download-suggestions]').onclick=downloadSuggestions}
async function loadPlaceSuggestions(){let area=document.querySelector('#suggestion-results'),type=document.querySelector('[name="suggest-type"]')?.value||'all',button=document.querySelector('[data-run-suggestions]');if(!area)return;button.disabled=true;button.textContent='Buscando…';area.innerHTML='<div class="empty"><span class="empty-icon">⌕</span><b>Buscando en Mendoza</b><p>Consultando fuentes públicas; puede demorar unos segundos.</p></div>';let bounds=mapObj?mapObj.getBounds().pad(0.12):null,region={south:-33.12,west:-69.25,north:-32.55,east:-68.25},south=bounds?Math.max(region.south,bounds.getSouth()):region.south,west=bounds?Math.max(region.west,bounds.getWest()):region.west,north=bounds?Math.min(region.north,bounds.getNorth()):region.north,east=bounds?Math.min(region.east,bounds.getEast()):region.east,box=`(${south},${west},${north},${east})`,filters={food:`nwr["amenity"~"restaurant|cafe|bar|pub|biergarten"]${box};`,hotels:`nwr["tourism"~"hotel|guest_house|hostel|motel"]${box};`,events:`nwr["leisure"="event_venue"]${box};nwr["amenity"~"events_venue|conference_centre|community_centre"]${box};`,all:`nwr["amenity"~"restaurant|cafe|bar|pub|biergarten|events_venue|conference_centre"]${box};nwr["tourism"~"hotel|guest_house|hostel|motel"]${box};nwr["leisure"="event_venue"]${box};`};if(south>=north||west>=east){area.innerHTML='<div class="empty"><b>No hay lugares en esta zona</b><p>Mové el mapa hacia Mendoza para buscar puntos cercanos.</p></div>';button.disabled=false;button.textContent='⌕ Buscar en Mendoza';return}let query=`[out:json][timeout:15];(${filters[type]||filters.all});out center 220;`;try{let payload=suggestionCache[query],lastError;if(!payload){for(const endpoint of ['https://overpass.private.coffee/api/interpreter','https://overpass-api.de/api/interpreter','https://maps.mail.ru/osm/tools/overpass/api/interpreter']){try{let res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({data:query}),signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error(`OpenStreetMap respondió ${res.status}`);payload=await res.json();if(!Array.isArray(payload.elements))throw Error(payload.remark||'El servicio de mapas respondió sin datos válidos');suggestionCache[query]=payload;if(Object.keys(suggestionCache).length>12)delete suggestionCache[Object.keys(suggestionCache)[0]];break}catch(error){payload=null;lastError=error}}if(!payload)throw lastError||Error('No respondió el servicio de mapas')}let known=new Set(db.places.map(p=>p.osmRef).filter(Boolean));suggestions=(payload.elements||[]).filter(e=>e.tags?.name&&(e.lat!==undefined||e.center)).map(e=>{let t=e.tags,category=osmCategory(t),street=[t['addr:street'],t['addr:housenumber']].filter(Boolean).join(' '),locality=t['addr:suburb']||t['addr:city']||t['addr:place']||'';return {osmRef:`${e.type}/${e.id}`,name:t.name,category,status:'Pendiente de visita',address:[street,locality].filter(Boolean).join(', '),lat:e.lat??e.center.lat,lng:e.lon??e.center.lon,contact:'',phone:t.phone||t['contact:phone']||'',email:t.email||t['contact:email']||'',notes:'Sugerencia de OpenStreetMap. Verificar la información antes de contactar.',next:'Confirmar datos y evaluar visita',visits:[],website:t.website||t['contact:website']||'',description:t['description:es']||t.description||(t.cuisine?`Cocina: ${t.cuisine.replaceAll(';',', ')}`:''),imageUrl:osmImage(t),sourceUrl:`https://www.openstreetmap.org/${e.type}/${e.id}`}}).filter(p=>!known.has(p.osmRef));renderSuggestionResults();plotSuggestions(true);if(!suggestions.length)area.innerHTML='<div class="empty"><span class="empty-icon">⌖</span><b>No hay lugares nuevos en esta búsqueda</b><p>Probá otra categoría o revisá los lugares ya guardados.</p></div>'}catch(err){area.innerHTML=`<div class="empty"><span class="empty-icon">!</span><b>No se pudo completar la búsqueda</b><p>${esc(err.message||'Verificá tu conexión e intentá de nuevo.')}</p><button class="btn btn-sm" data-run-suggestions>Reintentar</button></div>`;area.querySelector('[data-run-suggestions]')?.addEventListener('click',loadPlaceSuggestions)}finally{let b=document.querySelector('[data-run-suggestions]');if(b){b.disabled=false;b.textContent='⌕ Buscar de nuevo'}}}
function osmImage(t){let raw=t.image||t.wikimedia_commons||'';if(!raw)return '';if(raw.startsWith('File:'))return `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(raw.slice(5))}?width=480`;try{let url=new URL(raw);return url.protocol==='https:'?url.href:''}catch{return ''}}
function osmCategory(t){let v=t.amenity||t.leisure||t.tourism||'';if(['hotel','guest_house','hostel','motel'].includes(v))return 'Hotel';if(['event_venue','events_venue','conference_centre'].includes(v))return 'Salón de eventos';if(['bar','pub','biergarten'].includes(v))return 'Bar';if(['restaurant','cafe'].includes(v))return 'Restaurante';return 'Otro'}
function renderSuggestionResults(){let area=document.querySelector('#suggestion-results'),dl=document.querySelector('[data-download-suggestions]');if(!area)return;if(dl)dl.disabled=!suggestions.length;if(!suggestions.length)return;area.innerHTML=`<div class="suggestion-summary">${suggestions.length} lugar${suggestions.length===1?'':'es'} nuevo${suggestions.length===1?'':'s'} · podés guardarlos o descargarlos</div>${suggestions.length>60?`<div class="small-muted">Mostrando 60 resultados cercanos; la descarga incluye todos.</div>`:''}${suggestions.slice(0,60).map((p,i)=>`<article class="suggestion-row">${p.imageUrl?`<img class="suggestion-photo" src="${esc(p.imageUrl)}" alt="Imagen de ${esc(p.name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true">`:`<span class="suggestion-icon">${esc(p.category[0])}</span>`}<div class="suggestion-info"><b>${esc(p.name)}</b><small>${esc(p.category)}${p.address?' · '+esc(p.address):''}</small><p>${esc((p.description||'Descripción no disponible.').slice(0,180))}</p>${p.phone?`<small>${esc(p.phone)}</small>`:''}</div><label class="visited-toggle"><input type="checkbox" data-visited-suggestion="${i}" ${db.places.find(x=>x.osmRef===p.osmRef)?.status==='Visitado'?'checked':''}><span>Ya fuimos</span></label><button class="btn btn-sm" data-add-suggestion="${i}" ${db.places.some(x=>x.osmRef===p.osmRef)?'disabled':''}>＋ Agregar</button></article>`).join('')}<div class="osm-credit">Datos © OpenStreetMap · La presencia en OSM no indica popularidad, calidad ni vigencia.</div>`;area.querySelectorAll('[data-add-suggestion]').forEach(b=>b.onclick=()=>addSuggestion(Number(b.dataset.addSuggestion)));area.querySelectorAll('[data-visited-suggestion]').forEach(input=>input.onchange=()=>markSuggestionVisited(Number(input.dataset.visitedSuggestion),input.checked))}
function plotSuggestions(fit=false){if(!mapObj||!window.L)return;if(suggestionLayer)mapObj.removeLayer(suggestionLayer);suggestionLayer=L.layerGroup();let zoomLevel=mapObj.getZoom(),visible=mapObj.getBounds().pad(0.18),nearby=suggestions.filter(p=>visible.contains([Number(p.lat),Number(p.lng)])&&!db.places.some(saved=>saved.osmRef===p.osmRef));if(zoomLevel<14){let cells=new Map(),projected=nearby.map(p=>({p,point:mapObj.project([Number(p.lat),Number(p.lng)],zoomLevel)}));projected.forEach(({p,point})=>{let key=`${Math.floor(point.x/72)}:${Math.floor(point.y/72)}`;if(!cells.has(key))cells.set(key,[]);cells.get(key).push(p)});cells.forEach(group=>{let lat=group.reduce((sum,p)=>sum+Number(p.lat),0)/group.length,lng=group.reduce((sum,p)=>sum+Number(p.lng),0)/group.length;if(group.length===1){suggestionLayer.addLayer(makeSuggestionMarker(group[0],zoomLevel))}else{let icon=L.divIcon({className:'suggestion-cluster-icon',html:`<span class="suggestion-cluster">${group.length}</span>`,iconSize:[40,40],iconAnchor:[20,20]});let marker=L.marker([lat,lng],{icon,zIndexOffset:1100});marker.on('click',()=>mapObj.setView([lat,lng],Math.min(17,zoomLevel+2)));suggestionLayer.addLayer(marker)}})}else nearby.forEach(p=>suggestionLayer.addLayer(makeSuggestionMarker(p,zoomLevel)));suggestionLayer.addTo(mapObj);if(fit&&suggestionLayer.getLayers().length)mapObj.fitBounds(suggestionLayer.getBounds(),{padding:[24,24],maxZoom:13})}
function makeSuggestionMarker(p,zoomLevel){let labeled=zoomLevel>=15,icon=L.divIcon({className:'suggestion-div-icon',html:`<span class="map-marker suggestion-marker"><i>${esc(p.category[0])}</i></span>${labeled?`<span class="suggestion-map-label">${esc(p.name)}</span>`:''}`,iconSize:labeled?[200,42]:[38,42],iconAnchor:labeled?[18,38]:[19,38]});let marker=L.marker([Number(p.lat),Number(p.lng)],{icon,zIndexOffset:1000});marker.bindPopup(`<div class="suggestion-popup">${p.imageUrl?`<img src="${esc(p.imageUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.hidden=true">`:''}<b>${esc(p.name)}</b><small>${esc(p.category)}${p.address?' · '+esc(p.address):''}</small><p>${esc((p.description||'Descripción no disponible en OpenStreetMap.').slice(0,180))}</p><a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener">Ver ficha en OpenStreetMap ↗</a></div>`,{maxWidth:250});return marker}
function addSuggestion(i){let p=suggestions[i];if(!p)return;if(db.places.some(x=>x.osmRef===p.osmRef)){toast('Ese lugar ya está guardado');return}db.places.push({...p,id:uid()});suggestions.splice(i,1);save();renderSuggestionResults();renderTerritory();toast('Lugar agregado a tu mapa')}
function markSuggestionVisited(i,visited){let p=suggestions[i];if(!p)return;let saved=db.places.find(x=>x.osmRef===p.osmRef);if(!saved){saved={...p,id:uid(),visits:[]};db.places.push(saved)}saved.status=visited?'Visitado':'Pendiente de visita';saved.visits=saved.visits||[];saved.visits.push({date:new Date().toISOString().slice(0,10),note:visited?'Marcado como visita realizada':'Marcado como pendiente de visita'});save();renderTerritory();toast(visited?'Lugar marcado como visitado':'Lugar marcado como pendiente')}
function downloadSuggestions(){if(!suggestions.length)return;let rows=[['Nombre','Categoría','Dirección','Teléfono','Latitud','Longitud','Fuente'],...suggestions.map(p=>[p.name,p.category,p.address,p.phone,p.lat,p.lng,p.sourceUrl])],csv=rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(';')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'lugares-sugeridos-mendoza-openstreetmap.csv')}
function openPlace(id,coords){let p=db.places.find(x=>x.id===id);modal(p?'Editar lugar':'Agregar establecimiento',form(`${field('Nombre *','name',p?.name||'','','Ej. Restaurante o empresa')}${selectField('Categoría','category',['Restaurante','Bar','Hotel','Salón de eventos','Empresa gastronómica','Otro'].map(x=>[x,x]),p?.category||'Restaurante')}${field('Dirección','address',p?.address||'','','Calle y localidad')}${field('Contacto','contact',p?.contact||'')}${field('Teléfono','phone',p?.phone||'','tel')}${field('Correo','email',p?.email||'','email')}${selectField('Estado','status',['Sin investigar','Pendiente de visita','Contactado','Visitado','Oportunidad interesante','Descartado'].map(x=>[x,x]),p?.status||'Pendiente de visita')}${textarea('Notas','notes',p?.notes||'')}${field('Próximo paso','next',p?.next||'')}${field('Latitud (opcional)','lat',p?.lat??coords?.lat??'','number')}${field('Longitud (opcional)','lng',p?.lng??coords?.lng??'','number')}`,p?'Guardar cambios':'Registrar lugar'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));if(p)Object.assign(p,f);else{p={id:uid(),...f,visits:[]};db.places.push(p)}selectedPlace=p.id;save();closeModal();renderTerritory();toast(p?'Lugar guardado':'Lugar registrado')}}
function openVisit(id){let p=db.places.find(x=>x.id===id);modal('Registrar visita',form(`${field('Fecha','date',new Date().toISOString().slice(0,10),'date')}${textarea('Observaciones','note','','¿Qué conversaron?')}${field('Próximo paso','next',p?.next||'')}${selectField('Estado de contacto','status',['Contactado','Visitado','Oportunidad interesante','Pendiente de visita'].map(x=>[x,x]),'Visitado')}`, 'Guardar visita'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));p.visits=p.visits||[];p.visits.push({date:f.date,note:f.note});p.status=f.status;p.next=f.next;save();closeModal();renderTerritory();toast('Visita registrada')}}

// Los KPI y gráficos derivan exclusivamente de movimientos ingresados por el equipo.
let financePeriod='all',financeCategory='';
function renderFinance(){let list=db.movements.filter(x=>(financePeriod==='all'||x.date>=financePeriod)&&(!financeCategory||x.category===financeCategory));let income=list.filter(x=>x.type==='Ingreso').reduce((s,x)=>s+Number(x.amount),0),expense=list.filter(x=>x.type==='Gasto').reduce((s,x)=>s+Number(x.amount),0),investment=list.filter(x=>x.type==='Inversión').reduce((s,x)=>s+Number(x.amount),0);let budget=income-expense-investment;let periods=[['all','Todo el período'],['30','Últimos 30 días'],['90','Últimos 90 días'],['year','Este año']];app.innerHTML=head('ADMINISTRACIÓN · MOVIMIENTOS','Finanzas','Indicadores calculados a partir de tus registros. Sin cifras de ejemplo.',`<div class="toolbar"><button class="btn" data-action="export-finance">↓ Exportar CSV</button><button class="btn btn-primary" data-action="add-movement">＋ Registrar movimiento</button></div>`)+`<div class="toolbar" style="margin-bottom:13px">${selectField('','finance-period',periods,financePeriod)}${selectField('','finance-category',[['','Todas las categorías'],...Array.from(new Set(db.movements.map(x=>x.category))).map(c=>[c,c])],financeCategory)}</div><div class="finance-kpis">${[['Ingresos',income,'↗'],['Gastos',expense,'↘'],['Disponible',budget,'◈'],['Inversiones',investment,'◎']].map((x,i)=>`<div class="card kpi"><span class="kpi-icon">${x[2]}</span><div class="kpi-label">${x[0]}</div><div class="kpi-value">${db.movements.length?money(x[1]):'—'}</div><div class="kpi-meta">${db.movements.length?`${db.movements.length} movimiento${db.movements.length===1?'':'s'} en registros`:'Se calcula al cargar datos'}</div></div>`).join('')}</div><div class="finance-charts"><section class="card chart-box"><header class="card-head"><div><h2 class="card-title">Distribución de gastos</h2><span class="card-note">Por categoría</span></div></header>${db.movements.some(x=>x.type==='Gasto')?pieChart(list):`<div class="empty" style="padding:22px"><span class="empty-icon">◉</span><b>Sin gastos registrados</b><p>El gráfico aparecerá al agregar movimientos.</p></div>`}</section><section class="card chart-box"><header class="card-head"><div><h2 class="card-title">Ingresos y gastos</h2><span class="card-note">Evolución mensual · ARS</span></div><div class="chart-legend"><span><i class="legend-swatch" style="background:#5c78ed"></i>Ingresos</span><span><i class="legend-swatch" style="background:#51ba98"></i>Gastos</span></div></header>${db.movements.length?lineChart(list):`<div class="empty" style="padding:22px"><span class="empty-icon">⌁</span><b>Tu evolución financiera</b><p>Registrá ingresos o gastos para ver la tendencia por mes.</p></div>`}</section></div><div class="finance-bottom"><section class="card"><header class="card-head"><div><h2 class="card-title">Movimientos</h2><span class="card-note">Ingresos, gastos e inversiones</span></div><button class="btn btn-sm" data-action="add-movement">＋ Agregar</button></header>${list.length?`<div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Descripción</th><th>Categoría</th><th>Fecha</th><th>Tipo</th><th>Importe</th><th></th></tr></thead><tbody>${list.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.category)}</td><td>${dateFmt(x.date,{day:'numeric',month:'short',year:'numeric'})}</td><td>${pill(x.type,classForStatus(x.type==='Ingreso'?'Completado':'Pendiente'))}</td><td>${money(x.amount)}</td><td><button class="btn btn-sm" data-delete-movement="${x.id}" aria-label="Eliminar">×</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><span class="empty-icon">＄</span><b>Todavía no hay movimientos</b><p>Cargá ingresos, gastos o inversiones para que el panel calcule los indicadores.</p><button class="btn btn-sm btn-primary" data-action="add-movement">＋ Registrar movimiento</button></div>`}</section><section class="card"><header class="card-head"><div><h2 class="card-title">Excel de NEXO</h2><span class="card-note">Archivo privado del dispositivo</span></div></header><label class="file-zone" for="xlsx-file"><span class="empty-icon" style="margin:0 auto">↑</span><b>Subí una planilla</b><small>Excel .xlsx/.xls o CSV<br>Vista previa antes de importar</small><input id="xlsx-file" type="file" accept=".xlsx,.xls,.csv,text/csv" hidden></label>${db.xls?`<div class="file-info"><b>${esc(db.xls.name)}</b><small>${(db.xls.size/1024).toFixed(1)} KB · ${db.xls.sheets?.length?db.xls.sheets.length+' hojas':'archivo guardado'}</small></div><div style="padding:0 14px 12px;display:flex;gap:7px"><button class="btn btn-sm" data-action="download-xls">↓ Descargar</button><button class="btn btn-sm" data-action="remove-xls">Reemplazar</button></div>${db.xls.preview?`<div class="preview-box">${db.xls.preview}</div>`:''}`:'<div class="file-info"><small>La planilla original se guardará en este navegador. No se incorporarán datos financieros sin revisar la vista previa.</small></div>'}</section></div>`;
 app.querySelector('[name="finance-period"]').onchange=e=>{financePeriod=e.target.value;renderFinance()};app.querySelector('[name="finance-category"]').onchange=e=>{financeCategory=e.target.value;renderFinance()};app.querySelectorAll('[data-action="add-movement"]').forEach(b=>b.onclick=()=>openMovement());app.querySelector('[data-action="export-finance"]').onclick=exportFinance;app.querySelectorAll('[data-delete-movement]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este movimiento?')){db.movements=db.movements.filter(x=>x.id!==b.dataset.deleteMovement);save();renderFinance();toast('Movimiento eliminado')}});document.querySelector('#xlsx-file').onchange=handleXls;app.querySelector('[data-action="download-xls"]')?.addEventListener('click',downloadXls);app.querySelector('[data-action="remove-xls"]')?.addEventListener('click',()=>{if(confirm('¿Reemplazar el archivo guardado?')){db.xls=null;save();renderFinance()}})
}
function pieChart(list){let by={};list.filter(x=>x.type==='Gasto').forEach(x=>by[x.category]=(by[x.category]||0)+Number(x.amount));let total=Object.values(by).reduce((a,b)=>a+b,0),colors=['#657fee','#58b899','#e4ae57','#bb83c8','#e58181','#80a8c7'];let angle=-Math.PI/2,cx=92,cy=70,r=55,paths=Object.entries(by).map(([k,v],i)=>{let a=angle,b=angle+v/total*Math.PI*2,x1=cx+r*Math.cos(a),y1=cy+r*Math.sin(a),x2=cx+r*Math.cos(b),y2=cy+r*Math.sin(b),large=b-a>Math.PI?1:0;angle=b;return `<path d="M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2} Z" fill="${colors[i%colors.length]}" stroke="white" stroke-width="2"><title>${esc(k)}: ${money(v)}</title></path>`}).join('');return `<div style="display:flex;align-items:center;gap:22px"><svg viewBox="0 0 184 140" style="width:175px;max-width:52%"><circle cx="92" cy="70" r="55" fill="#f2f4f7"/>${paths}<text x="92" y="68" text-anchor="middle" fill="#33445d" font-size="9" font-weight="700">${money(total)}</text><text x="92" y="81" text-anchor="middle" fill="#98a1af" font-size="7">GASTOS</text></svg><div style="display:grid;gap:8px">${Object.entries(by).map(([k,v],i)=>`<div style="display:flex;align-items:center;gap:6px;font-size:9px;color:#707d90"><i class="legend-swatch" style="background:${colors[i%colors.length]}"></i>${esc(k)} <b style="margin-left:auto;color:#56647a">${Math.round(v/total*100)}%</b></div>`).join('')}</div></div>`}
function lineChart(list){let months=Array.from({length:6},(_,i)=>{let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-i));return {key:d.toISOString().slice(0,7),label:new Intl.DateTimeFormat('es-AR',{month:'short'}).format(d)}});let vals=t=>months.map(m=>list.filter(x=>x.date.startsWith(m.key)&&x.type===t).reduce((s,x)=>s+Number(x.amount),0));let inc=vals('Ingreso'),exp=vals('Gasto'),max=Math.max(1,...inc,...exp),points=v=>v.map((n,i)=>`${25+i*66},${126-n/max*104}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 360 150" preserveAspectRatio="none"><path d="M25 16V126H350" fill="none" stroke="#edf0f4"/><path d="M25 50H350M25 88H350" stroke="#f1f3f6"/><polyline points="${points(inc)}" fill="none" stroke="#5c78ed" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${points(exp)}" fill="none" stroke="#51ba98" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${inc.map((n,i)=>`<circle cx="${25+i*66}" cy="${126-n/max*104}" r="3" fill="#5c78ed"/>`).join('')}${exp.map((n,i)=>`<circle cx="${25+i*66}" cy="${126-n/max*104}" r="3" fill="#51ba98"/>`).join('')}${months.map((m,i)=>`<text x="${25+i*66}" y="145" font-size="8" text-anchor="middle" fill="#9aa3af">${m.label}</text>`).join('')}</svg>`}
function openMovement(){modal('Registrar movimiento',form(`${field('Descripción *','title','','','Ej. Alquiler de sala')}${selectField('Tipo','type',[['Ingreso','Ingreso'],['Gasto','Gasto'],['Inversión','Inversión']],'Gasto')}${field('Categoría *','category','','','Ej. Marketing')}${field('Importe (ARS) *','amount','','number','0')}${field('Fecha','date',new Date().toISOString().slice(0,10),'date')}${textarea('Nota','note')}`,'Guardar movimiento'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));f.amount=Number(f.amount);if(!f.amount||f.amount<0){toast('Ingresá un importe válido');return}db.movements.push({id:uid(),...f});save();closeModal();renderFinance();toast('Movimiento guardado')}}
function exportFinance(){let rows=[['Descripción','Tipo','Categoría','Importe ARS','Fecha','Nota'],...db.movements.map(x=>[x.title,x.type,x.category,x.amount,x.date,x.note||''])];let csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(';')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'nexo-movimientos.csv')}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function base64Buffer(buffer){let bytes=new Uint8Array(buffer),parts=[];for(let i=0;i<bytes.length;i+=32768)parts.push(String.fromCharCode(...bytes.subarray(i,i+32768)));return btoa(parts.join(''))}
async function handleXls(e){let file=e.target.files?.[0];if(!file)return;if(db.xls&&!confirm('Ya hay un archivo guardado. ¿Reemplazarlo?')){e.target.value='';return}try{let buffer=await file.arrayBuffer(),preview='',sheets=[];if(file.name.toLowerCase().endsWith('.csv')){let text=new TextDecoder().decode(buffer);preview=tablePreview(text.split(/\r?\n/).filter(Boolean).slice(0,7).map(r=>r.split(/[;,\t]/)))}else if(window.XLSX){let wb=XLSX.read(buffer,{type:'array'});sheets=wb.SheetNames;let first=wb.Sheets[sheets[0]];preview=tablePreview(XLSX.utils.sheet_to_json(first,{header:1,defval:''}).slice(0,7));}else preview='<p style="padding:8px">No se pudo leer la vista previa. Descargá el archivo para consultarlo.</p>';if(file.size>2*1024*1024){toast('El archivo supera 2 MB, no se puede guardar localmente');return}db.xls={name:file.name,size:file.size,data:base64Buffer(buffer),type:file.type,preview,sheets};save();renderFinance();toast('Planilla guardada; revisá la vista previa')}catch(err){console.error(err);toast('No se pudo leer el archivo. Probá con CSV o XLSX')}}
function tablePreview(rows){if(!rows?.length)return '<p style="padding:8px">La planilla no contiene filas para previsualizar.</p>';return `<table><tbody>${rows.map((r,i)=>`<tr>${r.map(v=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table>`}
function downloadXls(){let x=db.xls;if(!x)return;let bytes=Uint8Array.from(atob(x.data),c=>c.charCodeAt(0));download(new Blob([bytes],{type:x.type||'application/octet-stream'}),x.name)}

// Directorio común: equipo interno y organizaciones/contactos relevantes.
function metricRows(){return (db.webMetrics||[]).filter(x=>x.date&&x.date!=='total')}
function metricCsv(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('No se pudo leer el archivo.'));reader.onload=()=>{try{let text=String(reader.result||'').replace(/^\uFEFF/,'');let lines=text.split(/\r?\n/).filter(Boolean);if(lines.length<2)throw Error('El CSV no contiene filas de datos.');let parse=line=>{let out=[],v='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'&&line[i+1]==='"'&&q){v+='"';i++}else if(c==='"')q=!q;else if((c===','||c===';')&&!q){out.push(v);v=''}else v+=c}out.push(v);return out};let headers=parse(lines[0]).map(x=>x.trim().toLowerCase().replace(/[^a-z0-9áéíóúñ ]/g,''));let idx=terms=>headers.findIndex(h=>terms.some(t=>h===t||h.includes(t)));let di=idx(['date','day','fecha','time']),pi=idx(['pageviews','page views','views','vistas']),vi=idx(['visitors','unique visitors','visitantes']);if(pi<0||vi<0)throw Error('No reconocí las columnas. Se necesitan fecha, pageviews y visitors. Revisá que el CSV sea una exportación de Vercel Analytics.');let rows=lines.slice(1).map(parse).map(r=>({date:di>=0?new Date(r[di]).toISOString().slice(0,10):'total',pageviews:Number(String(r[pi]).replace(/[^0-9.-]/g,''))||0,visitors:Number(String(r[vi]).replace(/[^0-9.-]/g,''))||0})).filter(x=>x.pageviews||x.visitors);if(!rows.length)throw Error('No encontré valores de tráfico para importar.');resolve(rows)}catch(e){reject(e)}};reader.readAsText(file)})}
function metricsLine(rows){if(!rows.length)return `<div class="empty" style="padding:22px"><span class="empty-icon">⌁</span><b>Sin datos de tráfico todavía</b><p>Importá un CSV de Vercel Analytics para ver la evolución real.</p></div>`;let daily=rows.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-30),max=Math.max(1,...daily.map(x=>x.pageviews)),pts=daily.map((x,i)=>`${daily.length===1?50:8+i*84/(daily.length-1)},${112-x.pageviews/max*92}`).join(' ');return `<svg viewBox="0 0 100 125" preserveAspectRatio="none" class="metrics-chart" role="img" aria-label="Pageviews por día"><path d="M8 112H92M8 66H92M8 20H92" stroke="#e8ebf0"/><polyline points="${pts}" fill="none" stroke="#6478e8" stroke-width="2" vector-effect="non-scaling-stroke"/>${daily.map((x,i)=>`<circle cx="${daily.length===1?50:8+i*84/(daily.length-1)}" cy="${112-x.pageviews/max*92}" r="1.4" fill="#6478e8"><title>${esc(x.date)} · ${x.pageviews} pageviews</title></circle>`).join('')}</svg><div class="chart-axis"><span>${esc(daily[0].date)}</span><span>${esc(daily[daily.length-1].date)}</span></div>`}
function renderData(){if(dataView==='team'){renderTeam();return}let all=metricRows(),cutoff=metricsWindow==='all'?null:Date.now()-Number(metricsWindow)*86400000,rows=all.filter(x=>!cutoff||new Date(x.date+'T23:59:59').getTime()>=cutoff),pageviews=rows.reduce((s,x)=>s+Number(x.pageviews||0),0),visitors=rows.reduce((s,x)=>s+Number(x.visitors||0),0),spend=db.movements.filter(x=>x.type==='Gasto'&&(!cutoff||new Date(x.date+'T23:59:59').getTime()>=cutoff)).reduce((s,x)=>s+Number(x.amount||0),0);app.innerHTML=head('NEXO · INDICADORES','Datos de NEXO','Tráfico del sitio y movimientos registrados, calculados con los datos disponibles.',`<div class="toolbar"><select class="select" id="metric-period"><option value="30" ${metricsWindow==='30'?'selected':''}>Últimos 30 días</option><option value="90" ${metricsWindow==='90'?'selected':''}>Últimos 90 días</option><option value="all" ${metricsWindow==='all'?'selected':''}>Todo el período</option></select><button class="btn" data-action="show-team">♙ Equipo y contactos</button></div>`)+`<div class="finance-kpis"><div class="card kpi"><span class="kpi-icon">↗</span><div class="kpi-label">Pageviews</div><div class="kpi-value">${all.length?pageviews.toLocaleString('es-AR'):'—'}</div><div class="kpi-meta">${all.length?'Según exportación de Vercel Analytics':'Esperando datos de Vercel'}</div></div><div class="card kpi"><span class="kpi-icon">◉</span><div class="kpi-label">Visitantes diarios</div><div class="kpi-value">${all.length?visitors.toLocaleString('es-AR'):'—'}</div><div class="kpi-meta">Suma de visitantes diarios reportados</div></div><div class="card kpi"><span class="kpi-icon">＄</span><div class="kpi-label">Gastos registrados</div><div class="kpi-value">${db.movements.some(x=>x.type==='Gasto')?money(spend):'—'}</div><div class="kpi-meta">Desde los movimientos cargados en Finanzas</div></div><div class="card kpi"><span class="kpi-icon">▤</span><div class="kpi-label">Movimientos</div><div class="kpi-value">${db.movements.length||'—'}</div><div class="kpi-meta">${db.xls?`Planilla guardada: ${esc(db.xls.name)}`:'No hay planilla adjunta'}</div></div></div><div class="finance-charts"><section class="card chart-box"><header class="card-head"><div><h2 class="card-title">Tráfico del sitio</h2><span class="card-note">Pageviews por día · Vercel Analytics</span></div><label class="btn btn-sm" for="metrics-csv">↑ Importar CSV</label><input id="metrics-csv" type="file" accept=".csv,text/csv" hidden></header>${metricsLine(rows)}</section><section class="card chart-box"><header class="card-head"><div><h2 class="card-title">Movimientos de NEXO</h2><span class="card-note">Importes tomados de Finanzas · ${money(spend)}</span></div><button class="btn btn-sm" data-page-link="finanzas">Ver movimientos</button></header>${db.movements.length?`<div class="empty" style="padding:22px"><b>${db.movements.length} movimientos registrados</b><p>El detalle y los gráficos financieros están en Finanzas.</p></div>`:`<div class="empty" style="padding:22px"><span class="empty-icon">▤</span><b>Falta la planilla de movimientos</b><p>Adjuntá el Excel en Finanzas para consultar sus datos. No se muestra ningún importe inventado.</p><button class="btn btn-sm" data-page-link="finanzas">Abrir Finanzas</button></div>`}</section></div><section class="card" style="margin-top:14px;padding:20px"><h2 class="card-title">Conexión con Vercel Analytics</h2><p class="card-note" style="margin:8px 0 14px">La conexión automática requiere el proyecto de Vercel y un token privado configurado en el servidor. Por ahora podés importar la exportación CSV; queda guardada en este navegador.</p><button class="btn btn-sm" data-action="show-team">Equipo y contactos</button></section>`;
app.querySelector('#metric-period').onchange=e=>{metricsWindow=e.target.value;renderData()};app.querySelector('[data-action="show-team"]').onclick=()=>{dataView='team';renderData()};app.querySelectorAll('[data-page-link]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.pageLink});app.querySelector('#metrics-csv').onchange=async e=>{try{let rows=await metricCsv(e.target.files[0]);db.webMetrics=rows;save();toast(`${rows.length} filas importadas de Vercel Analytics`);renderData()}catch(err){toast(err.message||'No se pudo importar el CSV')}}}
function renderTeam(){let people=db.people.filter(p=>(teamTab==='equipo'?p.type==='Equipo':p.type!=='Equipo')&&(!teamQuery||`${p.name} ${p.role} ${p.org} ${p.email}`.toLowerCase().includes(teamQuery.toLowerCase()))&&(!teamStatus||p.status===teamStatus));let contacts=teamTab!=='equipo';app.innerHTML=head(contacts?'VÍNCULOS · ORGANIZACIONES':'PERSONAS · ORGANIZACIONES',contacts?'Contactos relevantes':'Equipo y contactos',contacts?'Personas, empresas y organizaciones importantes para NEXO.':'Personas, responsabilidades y vínculos relevantes para NEXO.',`<div class="team-tools"><button class="btn" data-action="back-data">← Datos de NEXO</button><input id="team-search" class="input" placeholder="⌕  Buscar nombre o empresa…" value="${esc(teamQuery)}"><button class="btn btn-primary" data-action="add-person">＋ Agregar ${contacts?'contacto':'persona'}</button></div>`)+`<div class="toolbar" style="margin-bottom:12px">${selectField('','team-status',[['','Todos los estados'],['Activo','Activo'],['Inactivo','Inactivo'],['Pendiente','Pendiente']],teamStatus)}</div><div class="team-tabs"><button data-team-tab="equipo" class="${teamTab==='equipo'?'active':''}">Equipo <span class="small-muted">${db.people.filter(p=>p.type==='Equipo').length}</span></button><button data-team-tab="contactos" class="${contacts?'active':''}">Contactos <span class="small-muted">${db.people.filter(p=>p.type!=='Equipo').length}</span></button></div>${people.length?`<div class="team-grid">${people.map(personCard).join('')}</div>`:`<section class="card empty"><span class="empty-icon">♧</span><b>${teamQuery?'No encontramos personas':contacts?'Todavía no hay contactos relevantes':'Todavía no hay perfiles'}</b><p>${teamQuery?'Probá con otro nombre o empresa.':contacts?'Guardá acá personas, empresas y organizaciones importantes para NEXO, con su rol, vías de contacto y notas.':'Agregá integrantes y contactos para ordenar responsabilidades y datos de referencia.'}</p>${!teamQuery?`<button class="btn btn-primary btn-sm" data-action="add-person">＋ Agregar ${contacts?'contacto':'persona'}</button>`:''}</section>`}`;
 app.querySelector('[data-action="back-data"]').onclick=()=>{dataView='metrics';renderData()};app.querySelector('#team-search').oninput=e=>{teamQuery=e.target.value;renderTeam();let x=document.querySelector('#team-search');x.focus();x.setSelectionRange(teamQuery.length,teamQuery.length)};app.querySelector('[name="team-status"]').onchange=e=>{teamStatus=e.target.value;renderTeam()};app.querySelectorAll('[data-team-tab]').forEach(b=>b.onclick=()=>{teamTab=b.dataset.teamTab;renderTeam()});app.querySelector('[data-action="add-person"]')?.addEventListener('click',()=>openPerson());app.querySelectorAll('[data-person]').forEach(c=>c.onclick=e=>{if(e.target.closest('[data-edit-person]'))return;openProfile(c.dataset.person)});app.querySelectorAll('[data-edit-person]').forEach(b=>b.onclick=e=>{e.stopPropagation();openPerson(b.dataset.editPerson)})}
let teamQuery='',teamStatus='';
function renderContacts(){teamTab='contactos';renderTeam()}
function renderObjectives(){db.objectives=db.objectives||[];let goals=db.objectives,total=db.objectives.length,done=goals.filter(g=>Number(g.current)>=Number(g.target)).length;app.innerHTML=head('PLANIFICACIÓN · RESULTADOS','Objetivos','Definí metas concretas y registrá el avance de NEXO.',`<button class="btn btn-primary" data-action="add-objective">＋ Nuevo objetivo</button>`)+`<div class="goal-summary"><div class="card goal-stat"><span class="kpi-label">Objetivos activos</span><b>${total-done}</b><small>En seguimiento</small></div><div class="card goal-stat"><span class="kpi-label">Completados</span><b>${done}</b><small>Meta alcanzada</small></div><div class="card goal-stat"><span class="kpi-label">Totales</span><b>${total}</b><small>Registrados en NEXO</small></div></div>${total?`<div class="goal-grid">${goals.map(g=>{let target=Math.max(1,Number(g.target)||1),current=Math.max(0,Number(g.current)||0),pct=Math.min(100,Math.round(current/target*100)),complete=current>=target;return `<article class="card goal-card"><div class="goal-card-top"><div><span class="eyebrow">${esc(g.category||'General')}</span><h2>${esc(g.title)}</h2></div><button class="person-menu" data-edit-objective="${g.id}" aria-label="Editar objetivo">···</button></div><div class="goal-progress-label"><b>${current.toLocaleString('es-AR')} <span>/ ${target.toLocaleString('es-AR')} ${esc(g.unit||'unidades')}</span></b>${pill(complete?'Completado':g.status||'En curso',complete?'green':classForStatus(g.status||'En curso'))}</div><div class="goal-progress"><span style="width:${pct}%"></span></div><div class="goal-card-meta"><b>${pct}%</b><span>${g.due?`Fecha límite: ${dateFmt(g.due,{day:'numeric',month:'short',year:'numeric'})}`:'Sin fecha límite'}</span></div>${g.notes?`<p class="goal-notes">${esc(g.notes)}</p>`:''}<div class="goal-card-actions"><button class="btn btn-sm btn-primary" data-progress-objective="${g.id}" ${complete?'disabled':''}>＋ Registrar avance</button><button class="btn btn-sm" data-edit-objective="${g.id}">Editar</button><button class="btn btn-sm btn-quiet" data-delete-objective="${g.id}">Eliminar</button></div></article>`}).join('')}</div>`:`<section class="card empty"><span class="empty-icon">◎</span><b>Todavía no hay objetivos</b><p>Creá una meta como entrevistar a 100 personas y 15 empresas. Vas a poder actualizar el progreso y ver cuánto falta para alcanzarla.</p><button class="btn btn-primary btn-sm" data-action="add-objective">＋ Crear primer objetivo</button></section>`}`;
 app.querySelector('[data-action="add-objective"]')?.addEventListener('click',()=>openObjective());app.querySelectorAll('[data-edit-objective]').forEach(b=>b.onclick=()=>openObjective(b.dataset.editObjective));app.querySelectorAll('[data-progress-objective]').forEach(b=>b.onclick=()=>openObjectiveProgress(b.dataset.progressObjective));app.querySelectorAll('[data-delete-objective]').forEach(b=>b.onclick=()=>{let g=goals.find(x=>x.id===b.dataset.deleteObjective);if(g&&confirm(`¿Eliminar el objetivo “${g.title}”?`)){db.objectives=goals.filter(x=>x.id!==g.id);save();renderObjectives();toast('Objetivo eliminado')}})}
function openObjective(id){db.objectives=db.objectives||[];let g=db.objectives.find(x=>x.id===id);modal(g?'Editar objetivo':'Nuevo objetivo',form(`${field('Objetivo *','title',g?.title||'','','Ej. Entrevistar personas')}${field('Área','category',g?.category||'','','Ej. Investigación')}${field('Meta total *','target',g?.target||'','number','100')}${field('Avance actual','current',g?.current||0,'number','0')}${field('Unidad de medida *','unit',g?.unit||'personas','','Ej. personas, empresas, eventos')}${field('Fecha límite','due',g?.due||'','date')}${selectField('Estado','status',[['En curso','En curso'],['Pausado','Pausado']],g?.status||'En curso')}${textarea('Notas','notes',g?.notes||'')}`,g?'Guardar cambios':'Crear objetivo'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));f.target=Number(f.target);f.current=Number(f.current)||0;if(!Number.isFinite(f.target)||f.target<=0||!Number.isFinite(f.current)||f.current<0){toast('La meta debe ser mayor que cero y el avance no puede ser negativo');return}if(g)Object.assign(g,f);else db.objectives.push({id:uid(),...f});save();closeModal();renderObjectives();toast(g?'Objetivo actualizado':'Objetivo creado')}}
function openObjectiveProgress(id){let g=db.objectives.find(x=>x.id===id);if(!g)return;modal(`Registrar avance · ${esc(g.title)}`,form(`${field(`Cantidad de ${g.unit} alcanzada *`,'amount','','number','1')}${textarea('Nota del avance','note','','Ej. Entrevistas realizadas esta semana')}`,'Sumar al progreso'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget)),amount=Number(f.amount);if(!Number.isFinite(amount)||amount<=0){toast('Ingresá una cantidad mayor que cero');return}g.current=Number(g.current||0)+amount;g.updates=g.updates||[];g.updates.push({date:new Date().toISOString().slice(0,10),amount,note:f.note||''});save();closeModal();renderObjectives();toast('Progreso actualizado')}}
function personCard(p){let initials=(p.name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();return `<article class="card person-card" data-person="${p.id}"><div class="person-top"><span class="person-avatar">${esc(initials)}</span><div class="person-info"><h3>${esc(p.name)}</h3><p>${esc(p.role||p.type)}${p.org?' · '+esc(p.org):''}</p></div><button class="person-menu" data-edit-person="${p.id}">···</button></div><div class="person-details"><div class="person-detail"><span>✉</span>${esc(p.email||'Sin correo')}</div><div class="person-detail"><span>⌕</span>${esc(p.phone||'Sin teléfono')}</div>${p.notes?`<div class="person-detail"><span>≡</span>${esc(p.notes)}</div>`:''}</div><div class="person-foot">${pill(p.status,classForStatus(p.status))}<span class="small-muted">${p.type==='Equipo'?'Integrante':'Contacto'}</span></div></article>`}
function openPerson(id){let p=db.people.find(x=>x.id===id);modal(p?'Perfil de persona':'Agregar persona o contacto',form(`${field('Nombre completo *','name',p?.name||'','','Nombre y apellido')}${selectField('Tipo de perfil','type',[['Equipo','Equipo interno'],['Empresa','Empresa u organización'],['Contacto','Contacto individual']],p?.type||(teamTab==='equipo'?'Equipo':'Contacto'))}${field('Rol o cargo','role',p?.role||'','','Ej. Coordinación')}${field('Empresa u organización','org',p?.org||'')}${field('Correo','email',p?.email||'','email')}${field('Teléfono','phone',p?.phone||'','tel')}${selectField('Estado','status',['Activo','Inactivo','Pendiente'].map(x=>[x,x]),p?.status||'Activo')}${textarea('Notas','notes',p?.notes||'')}${p?`<p class="small-muted">Historial: perfil creado en este espacio local. Las asignaciones y actividad ampliada se habilitarán con tareas compartidas.</p>`:''}`,p?'Guardar cambios':'Crear perfil'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));if(p)Object.assign(p,f);else db.people.push({id:uid(),...f});save();closeModal();renderTeam();toast(p?'Perfil actualizado':'Perfil agregado')}}
function openProfile(id){let p=db.people.find(x=>x.id===id);if(!p)return;let tasks=p.tasks||[],history=p.history||[];modal('Ficha de persona',`<div class="modal-form"><div class="person-top"><span class="person-avatar">${esc((p.name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase())}</span><div class="person-info"><h3>${esc(p.name)}</h3><p>${esc(p.role||p.type)}${p.org?' · '+esc(p.org):''}</p></div>${pill(p.status,classForStatus(p.status))}</div><div class="person-details"><div class="person-detail">✉ ${esc(p.email||'Sin correo')}</div><div class="person-detail">⌕ ${esc(p.phone||'Sin teléfono')}</div><div class="person-detail">≡ ${esc(p.notes||'Sin notas')}</div></div><section><h3 class="card-title">Tareas asignadas <button class="btn btn-sm" data-profile-task>＋ Agregar</button></h3>${tasks.length?tasks.map(t=>`<div class="event-item"><input type="checkbox" data-task-done="${t.id}" ${t.done?'checked':''}><div><b>${esc(t.title)}</b><small>${t.due?`Vence ${dateFmt(t.due)}`:'Sin fecha límite'} · ${t.done?'Completada':'Pendiente'}</small></div><button data-delete-task="${t.id}">×</button></div>`).join(''):'<p class="small-muted">No hay tareas asignadas.</p>'}</section><section><h3 class="card-title">Actividad reciente</h3>${history.length?history.slice().reverse().slice(0,5).map(h=>`<div class="event-item"><span class="event-marker"></span><div><b>${esc(h.text)}</b><small>${dateFmt(h.date,{day:'numeric',month:'short',year:'numeric'})}</small></div></div>`).join(''):'<p class="small-muted">Todavía no hay actividad registrada.</p>'}</section><div class="form-actions"><button class="btn" data-close>Cerrar</button><button class="btn btn-primary" data-profile-edit="${p.id}">Editar perfil</button></div></div>`);document.querySelector('[data-profile-edit]').onclick=()=>openPerson(p.id);document.querySelector('[data-profile-task]').onclick=()=>{modal(`Nueva tarea · ${esc(p.name)}`,form(`${field('Tarea *','title','','','Ej. Compartir propuesta')}${field('Fecha límite','due','','date')}`,'Asignar tarea'));document.querySelector('.modal-form').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));p.tasks=p.tasks||[];p.tasks.push({id:uid(),title:f.title,due:f.due,done:false});p.history=p.history||[];p.history.push({date:new Date().toISOString().slice(0,10),text:`Tarea asignada: ${f.title}`});save();openProfile(p.id)}};document.querySelectorAll('[data-task-done]').forEach(c=>c.onchange=()=>{let t=tasks.find(x=>x.id===c.dataset.taskDone);if(t){t.done=c.checked;p.history=p.history||[];p.history.push({date:new Date().toISOString().slice(0,10),text:`Tarea ${t.done?'completada':'reabierta'}: ${t.title}`});save();openProfile(p.id)}});document.querySelectorAll('[data-delete-task]').forEach(b=>b.onclick=()=>{p.tasks=tasks.filter(t=>t.id!==b.dataset.deleteTask);save();openProfile(p.id)})}

// Acciones comunes del lienzo modal y navegación.
document.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModal();let edit=e.target.closest('[data-edit-event]');if(edit)openEvent(edit.dataset.editEvent)});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
document.addEventListener('dragstart',e=>{let chip=e.target.closest('.event-chip');if(chip){chip.draggable=true;e.dataTransfer.setData('text/plain',chip.dataset.event)}});document.addEventListener('dragover',e=>{if(e.target.closest('.day'))e.preventDefault()});document.addEventListener('drop',e=>{let day=e.target.closest('.day'),id=e.dataTransfer?.getData('text/plain');if(!day||!id)return;e.preventDefault();let item=db.events.find(x=>x.id===id);if(item){item.date=day.dataset.day;selectedDay=item.date;save();renderCalendar();toast('Evento movido')}});
new MutationObserver(()=>document.querySelectorAll('.event-chip').forEach(x=>x.draggable=true)).observe(app,{childList:true,subtree:true});
window.addEventListener('resize',()=>{if(page==='ideas')drawEdges()});render();

